'use strict';
import {createPlayback} from './playback.js';
import {createLearningV2,findLinkedWord} from './learning-v2.js';
const playback=createPlayback();
let hideEnglish=false,hideChinese=false,slowAudio=false,reviewAll=false,reviewItems=[],learningState=null,practiceProgress=[],trainingItems=[],trainingIndex=0,trainingReview=false,activeDialogue=null,practiceRole='a',practiceTurn=0;
document.addEventListener('visibilitychange',()=>{if(document.hidden){playback.stop();learningV2.pause();}});
window.addEventListener('pagehide',()=>{playback.stop();learningV2.pause();});
const $=s=>document.querySelector(s);
const classicPages=new Set(['classic','words','phrases','scenes','review','v2','membership','account','admin']);
function routePage(search=''){const query=new URLSearchParams(search);return classicPages.has(query.get('page'))?query.get('page'):query.get('version')==='classic'?'classic':'home';}
function pageUrl(p){return p==='home'?'/':'/?version=classic'+(p==='classic'?'':'&page='+encodeURIComponent(p));}
let lang=localStorage.getItem('ee_lang')||'zh',page=routePage(location.search),user=null,catalog={counts:[],scenes:[],materials:[]},progress=[],orders=[],users=[],adminOrders=[],gmailStatus={},search='',filter='all',scene='all';
const t=(zh,en)=>lang==='zh'?zh:en;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const learningV2=createLearningV2({request,getUser:()=>user,getCatalog:()=>catalog,getLanguage:()=>lang,playback,signIn:()=>auth('login'),openDialogue:async id=>{practiceCategory='all';practiceScene='all';await navigate('scenes');const button=[...document.querySelectorAll('[data-dialogue]')].find(b=>b.dataset.dialogue===id);if(button)await button.onclick();}});
const statuses=()=>[['learned',t('已学习','Learned')],['unmastered',t('未掌握','Learning')],['mastered',t('已掌握','Mastered')],['review',t('待复习','To review')]];
function toast(message){$('#notice').textContent=message;$('#notice').style.display='block';setTimeout(()=>$('#notice').style.display='none',4500);}
async function request(path,method='GET',body){const r=await fetch('/api'+path,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok){const error=new Error(data.error);error.status=r.status;throw error;}return data;}
async function refresh(){
 try{user=(await request('/me')).user;}catch(error){if(error.status===401)user=null;else throw error;}
 catalog=await request('/catalog');
 if(user&&!user.must_change_password){
  const [p,l,d,r]=await Promise.all([request('/progress'),request('/learning-state'),request('/practice-progress'),request(reviewAll?'/review/all':'/review')]);
  progress=p.progress;learningState=l.state;practiceProgress=d.practice;reviewItems=r.items;
 }else{progress=[];learningState=null;practiceProgress=[];reviewItems=[];}
 if(user?.must_change_password)page='account';
}
async function syncLearning(){
 if(!user)return;
 const [p,r]=await Promise.all([request('/progress'),request(reviewAll?'/review/all':'/review')]);progress=p.progress;reviewItems=r.items;
}
const dateLabel=value=>new Date(value).toLocaleString(lang==='zh'?'zh-CN':'en');
function audioControls(id){return `<div class="audio"><button data-speak="${esc(id)}" data-speed="normal" aria-pressed="${!slowAudio}">◖)) ${t('正常发音','Normal')}</button><button data-speak="${esc(id)}" data-speed="slow" aria-pressed="${slowAudio}">◷ ${t('慢速发音','Slow')}</button><button data-repeat="${esc(id)}">↻ ${t('重复播放','Repeat')}</button><button data-shadow="${esc(id)}">${t('听一句，跟读一句','Listen & repeat aloud')}</button><button data-stop>${t('停止','Stop')}</button></div><p class="help playback-phase" role="status" aria-live="polite"></p>`;}
function visibilityControls(){return `<div class="practice-options"><button data-hide="en" aria-pressed="${hideEnglish}">${hideEnglish?t('显示英文','Show English'):t('隐藏英文 · 练听力','Hide English · Listen')}</button><button data-hide="zh" aria-pressed="${hideChinese}">${hideChinese?t('显示中文','Show Chinese'):t('隐藏中文 · 试着理解','Hide Chinese · Understand')}</button><button id="slow-audio" aria-pressed="${slowAudio}">${slowAudio?t('重复/陪练：慢速','Repeat/dialogue: slow'):t('重复/陪练：正常','Repeat/dialogue: normal')}</button></div>`;}
function statusControls(m){const state=progress.find(p=>p.material_id===m.id);return `<div class="statuses">${statuses().map(([v,l])=>`<button data-status="${v}" data-material="${esc(m.id)}" class="${state?.status===v?'selected':''}" aria-pressed="${state?.status===v}">${l}</button>`).join('')}</div>${state?.next_review_at?`<p class="help">${t('下次复习：','Next review: ')}${esc(dateLabel(state.next_review_at))}</p>`:''}`;}
function linkedPhraseText(m){return m.kind!=='phrase'?esc(m.english):m.english.split(/([A-Za-z]+(?:['’-][A-Za-z]+)*)/g).map(token=>/^[A-Za-z]/.test(token)?`<button class="v2-token" data-v2-token="${esc(token)}" data-v2-phrase="${esc(m.id)}" title="${t('点击查看词义','Tap for meaning')}">${esc(token)}</button>`:esc(token)).join('');}
function materialCard(m,trainer=false){return `<article class="material ${trainer?'trainer-card':''}"><span class="eyebrow">${m.kind==='word'?t('第一步 · 听懂一个词','Step 1 · Hear a word'):t('第二步 · 说出一句话','Step 2 · Say a phrase')}</span><p class="help">${levelLabel(m.difficulty)}</p>${hideEnglish?`<p class="hidden-copy">${t('英文已隐藏，试着听懂。','English hidden. Try listening.')}</p>`:`<h3 lang="en">${linkedPhraseText(m)}</h3>`}${hideChinese?`<p class="hidden-copy">${t('中文已隐藏','Chinese hidden')}</p>`:`<p lang="zh-CN">${esc(m.chinese)}</p>`}${audioControls(m.id)}${!trainer?`<button class="outline" data-train="${esc(m.id)}">${t('专心听说练习','Focus on listening & speaking')}</button>`:''}${statusControls(m)}<div class="v2-actions"><button data-v2-related="${esc(m.id)}">${t('联想学习','Explore links')}</button><button data-v2-listen="${esc(m.id)}">${t('先听后看','Listen first')}</button><button data-v2-expression="${esc(m.id)}">${t('看中文说英语','Speak from Chinese')}</button></div></article>`;}

const mockEnabled=()=>catalog.features?.mockCheckout===true;
const count=kind=>catalog.counts.find(c=>c.kind===kind)?.count||0;
const labelMembership=u=>u.membership==='lifetime'?t('永久会员','Lifetime'):u.hasAccess?t('试用会员','Trial'):t('免费用户','Free');
function empty(){return `<div class="empty"><div class="emptyicon">▤</div><h3>${t('教材正在准备中','Lessons are being prepared')}</h3><p>${t('完整教材包含 500 个基础单词、200 个实用短句及 20 个场景。<br>你也可以先体验下方的补充陪练。','The full curriculum contains 500 words, 200 phrases and 20 scenes.<br>You can try the supplementary conversations in the meantime.')}</p></div>`;}

function versionHome(){return `<section class="version-picker" aria-labelledby="version-heading"><span class="eyebrow">EASY ENGLISH · CHOOSE YOUR PATH</span><h1 id="version-heading">${t('选择你的英语学习版本','Choose your English learning path')}</h1><p class="muted">${t('从喜欢的方式开始，随时回来切换。','Start your way. Come back and switch anytime.')}</p><div class="version-cards" aria-label="${t('学习版本','Learning versions')}"><a class="version-card version-classic" href="/?version=classic" data-page="classic" data-version="classic"><span class="version-number" aria-hidden="true">1.0</span><h2>${t('简单英语1.0 经典版','Easy English 1.0 · Classic')}</h2><p>${t('500个基础单词、200条实用短句、20个生活与商务场景。','500 essential words, 200 useful phrases, and 20 everyday and business scenes.')}</p><span class="version-cta">${t('进入经典版','Enter Classic')} <span aria-hidden="true">→</span></span></a><a class="version-card version-modern" href="/ogden" data-version="modern"><span class="version-number" aria-hidden="true">2.0</span><h2>${t('简单英语2.0 现代基础英语','Easy English 2.0 · Modern Basic English')}</h2><p>${t('850个现代核心词，练习词语组合、主动表达、听力与开口。','850 modern core words, with combinations, expression, listening and speaking.')}</p><span class="version-cta">${t('进入现代基础英语','Enter Modern Basic English')} <span aria-hidden="true">→</span></span></a></div><p class="version-shared">${t('一个账号，两个学习版本。99元终身会员权益共用，无需重复购买；两版学习进度分别保留。免费内容与试用权限沿用现有规则。','One account, two learning paths. Your CNY 99 lifetime membership covers both; no second purchase. Progress is saved separately. Existing free-content and trial rules apply.')}</p><div class="version-account">${user?`<button class="outline" data-page="account">${t('查看我的账号','My account')}</button>`:`<button class="primary" data-auth="login">${t('登录并同步学习记录','Sign in to sync progress')}</button>`}<button class="outline" data-page="membership">${t('查看共用会员权益','Shared membership')}</button></div></section>`;}

function home(){
 const due=progress.filter(p=>new Date(p.next_review_at).getTime()<=Date.now()).length;
 return `<span class="eyebrow">LISTEN · SPEAK · CONNECT</span><h1>${t('先听懂，再开口。','Listen first. Then speak.')}</h1><div class="muted">${t('为零基础成年人设计。从一个词、一句话，到简单交流。','For adult beginners. From one word to a short conversation.')}</div>
 <section class="hero"><div class="herotext"><span class="eyebrow">简单英语 EASY ENGLISH</span><h2>${t('今天学多少，<br>由你决定。','Learn as much<br>as you like.')}</h2><p>${t('不必先学复杂语法。听一听、跟着说，按自己的节奏进步。<br>没有打卡要求，也没有每日数量限制。','No complicated grammar to start. Listen, repeat, and learn at your pace.<br>No required check-ins. No daily limits.')}</p><div class="hero-actions"><button class="primary" data-continue>${t('继续学习','Continue learning')} ↗</button><button class="outline" data-page="review">${t('开始复习','Start review')}${due?' · '+due:''}</button></div></div><div class="heroart" aria-hidden="true"><div class="orbit"><div class="book">Easy<br>English<small>LISTEN. SPEAK. CONNECT.</small></div></div><span class="spark">✦</span></div></section>
 <div class="sectionhead"><h2>${t('一步一步，学会简单交流','A gentle path to conversation')}</h2><small>${t('建议顺序，随时自由选择','A suggested path. Always your choice.')}</small></div><div class="courses learning-path">${[['words','01',t('单词 · 先听懂','Words · Listen first'),t('从最简单的词开始，听发音、跟着读。','Start with simple words. Listen and repeat.')],['phrases','02',t('短句 · 开口说','Phrases · Start speaking'),t('用常用短句表达，不急着学复杂语法。','Use everyday phrases without complicated grammar.')],['scenes','03',t('场景 · 真实交流','Scenes · Have a conversation'),t('选择一个角色，把听懂的内容说出来。','Choose a role and practise a short conversation.')]].map(([p,n,title,desc])=>`<article class="course"><div class="courseicon">${n}</div><h3>${title}</h3><p>${desc}</p><button class="outline" data-page="${p}">${t('自由练习','Explore freely')} ↗</button></article>`).join('')}</div>
 <div class="banner"><div><strong>${t('少一点设置，多一点开口。','Less setup. More speaking.')}</strong><p>${t('听正常或慢速发音，隐藏文字练听力，重复播放后留出时间跟读。随时开始，也随时停下。','Listen normally or slowly, hide the text, and repeat with speaking pauses. Start and stop whenever you like.')}</p></div></div>
 <div class="stats"><div class="stat"><span>${t('基础单词','Essential words')}</span><strong>${count('word')}<small>/ 500</small></strong></div><div class="stat"><span>${t('实用短句','Useful phrases')}</span><strong>${count('phrase')}<small>/ 200</small></strong></div><div class="stat"><span>${t('学习场景','Learning scenes')}</span><strong>${catalog.scenes.length}<small>/ 20</small></strong></div><div class="stat"><span>${t('我已掌握','Mastered')}</span><strong>${progress.filter(p=>p.status==='mastered').length}</strong></div></div>${!count('word')?empty():''}<div class="banner"><div><strong>${t('试着把英语用起来：场景陪练','Put English to use: conversation practice')}</strong><p>${t('生活、旅游和商务场景，选一个角色就能开始。','Life, travel and business. Choose a role and start speaking.')}</p></div><button data-page="scenes">${t('开始交流','Try a conversation')}</button></div>`;
}
function dialogueList(){const visible=(catalog.dialogues||[]).filter(d=>(practiceCategory==='all'||d.category===practiceCategory)&&(practiceScene==='all'||d.scene_id===practiceScene));return `<section class="dialogue-list"><div class="sectionhead"><div><h2>${t('预设场景陪练','Preset conversation practice')}</h2><p class="help">${t('20 个分级场景，每个场景 5 段完整对话。选择角色，先听，再自己说，无需付费 AI。','20 graded scenes with 5 complete conversations each. Choose a role, listen, then speak. No paid AI.')}</p></div></div><div class="toolbar"><select id="practice-category" aria-label="${t('陪练分类','Practice category')}"><option value="all">${t('全部分类','All categories')}</option><option value="life" ${practiceCategory==='life'?'selected':''}>${t('生活','Life')}</option><option value="business" ${practiceCategory==='business'?'selected':''}>${t('商务','Business')}</option><option value="travel" ${practiceCategory==='travel'?'selected':''}>${t('旅游','Travel')}</option></select><select id="practice-scene" aria-label="${t('陪练场景','Practice scene')}"><option value="all">${t('全部场景','All scenes')}</option>${catalog.scenes.map(s=>`<option value="${esc(s.id)}" ${practiceScene===s.id?'selected':''}>${esc(lang==='zh'?s.title_zh:s.title_en)} · ${levelLabel(s.difficulty)}</option>`).join('')}</select></div>${catalog.locked?`<p class="help">${t('当前显示免费对话，试用或永久会员可练习全部 100 段课程对话。','Free conversations are shown. Trial and lifetime members can practise all 100 curriculum dialogues.')}</p>`:''}<div class="courses">${visible.map(d=>{const saved=practiceProgress.find(p=>p.dialogue_id===d.id);return `<article class="course"><span class="badge">${categoryLabel(d.category)} · ${d.scene_id?levelLabel(d.difficulty):t('补充练习','Supplement')}</span><h3>${esc(lang==='zh'?d.title_zh:d.title_en)}</h3><p>${esc(catalog.scenes.find(s=>s.id===d.scene_id)?.[lang==='zh'?'title_zh':'title_en']||t('免费补充陪练','Free supplementary practice'))}<br>${t('简短对话，自由重复练习','A short conversation. Repeat whenever you like.')}${saved?'<br>'+t('云端已保存 · 完成 ','Cloud saved · Completed ')+saved.completed_count+t(' 次',' times'):''}</p><button class="primary" data-dialogue="${esc(d.id)}">${saved&&saved.turn_index<d.turns.length?t('继续陪练','Resume practice'):t('开始陪练','Start practice')}</button></article>`;}).join('')}</div>${!visible.length?`<div class="empty"><h3>${t('当前分类暂无可用对话','No accessible conversations for this selection')}</h3><p>${catalog.locked?t('可以选择免费场景，或查看会员以练习完整教材。','Choose a free scene or check membership for full access.'):t('试试其他分类或场景。','Try another category or scene.')}</p>${catalog.locked?`<button data-page="membership">${t('查看会员','Membership')}</button>`:''}</div>`:''}</section>`;}
let practiceCategory='all',practiceScene='all',difficulty='all',category='all';
const levelLabel=value=>Number(value)===3?t('三级 · 交流应用','Level 3 · Practical'):Number(value)===2?t('二级 · 日常表达','Level 2 · Everyday'):t('一级 · 零基础','Level 1 · Starter');
const categoryLabel=value=>value==='travel'?t('旅游','Travel'):value==='business'?t('商务','Business'):t('生活','Life');
function learning(){
 const isScenes=page==='scenes',isReview=page==='review',kind=page==='words'?'word':'phrase';
 const title=isReview?t('先复习还不熟悉的内容','Revisit what feels difficult'):isScenes?t('把英语用起来','Put your English to use'):page==='words'?t('从最简单的单词开始','Start with the simplest words'):t('用短句开口表达','Speak with everyday phrases');
 const stateByMaterial=new Map(progress.map(p=>[p.material_id,p.status]));
 const availableMaterials=(isReview?reviewItems:catalog.materials).filter(m=>(difficulty==='all'||m.difficulty===Number(difficulty))&&(category==='all'||catalog.scenes.find(s=>s.id===m.scene_id)?.category===category)&&(isReview||isScenes||m.kind===kind)&&(scene==='all'||m.scene_id===scene)&&(m.english+' '+m.chinese).toLowerCase().includes(search.toLowerCase()));
 const statusCounts=new Map(statuses().map(([value])=>[value,0]));
 for(const material of availableMaterials){const status=stateByMaterial.get(material.id);if(statusCounts.has(status))statusCounts.set(status,statusCounts.get(status)+1);}
 const materials=availableMaterials.filter(m=>filter==='all'||stateByMaterial.get(m.id)===filter);
 const countedLabel=(label,total)=>t(`${label}（${total}）`,`${label} (${total})`);
 return `<span class="eyebrow">LISTEN · REPEAT · TRY IT</span><h1>${title}</h1><p class="muted">${t('先听几次，再跟着说。一次学多少、什么时候停，都由你决定。','Listen a few times, then say it aloud. You decide how much to learn and when to stop.')}</p>${isScenes?dialogueList():''}
 ${!user?`<button class="outline" data-auth="login">${t('登录，云端同步学习与复习进度','Sign in to sync learning and review')}</button>`:''}
 ${isReview?`<div class="banner"><div><strong>${t('未掌握优先，不强制完成','Difficult items first. No obligation to finish.')}</strong><p>${t('系统根据你标记的状态安排下次复习，也可以随时主动复习全部已学内容。','Your learning state sets the next review time. You can also review any learned item early.')}</p></div></div><div class="toolbar"><button data-review-mode="due" class="${!reviewAll?'primary':''}" aria-pressed="${!reviewAll}">${t('到期复习','Due now')}</button><button data-review-mode="all" class="${reviewAll?'primary':''}" aria-pressed="${reviewAll}">${t('主动复习全部已学','Review all learned')}</button>${materials.length?`<button class="primary" data-start-review>${t('开始听说复习','Start speaking review')}</button>`:''}</div>`:catalog.locked?`<div class="banner"><div><strong>${t('免费内容开放学习','Free lessons are available')}</strong><p>${t('试用或永久会员可学习完整教材。','Trial and lifetime members can access the full curriculum.')}</p></div><button data-page="membership">${t('查看会员','Membership')}</button></div>`:''}
 <div class="toolbar"><select id="difficulty" aria-label="${t('难度','Difficulty')}"><option value="all">${t('全部难度','All levels')}</option>${[1,2,3].map(n=>`<option value="${n}" ${difficulty===String(n)?'selected':''}>${levelLabel(n)}</option>`).join('')}</select><select id="category" aria-label="${t('教材分类','Lesson category')}"><option value="all">${t('全部分类','All categories')}</option>${['life','travel','business'].map(c=>`<option value="${c}" ${category===c?'selected':''}>${categoryLabel(c)}</option>`).join('')}</select><input id="search" type="search" placeholder="${t('搜索英文或中文…','Search English or Chinese…')}" value="${esc(search)}" aria-label="${t('搜索教材','Search lessons')}"><select id="scene" aria-label="${t('场景分类','Scene category')}"><option value="all">${t('全部场景','All scenes')}</option>${catalog.scenes.map(s=>`<option value="${esc(s.id)}" ${scene===s.id?'selected':''}>${esc(lang==='zh'?s.title_zh:s.title_en)}</option>`).join('')}</select><select id="filter" aria-label="${t('学习状态','Learning state')}"><option value="all" ${filter==='all'?'selected':''}>${countedLabel(t('全部状态','All states'),availableMaterials.length)}</option>${statuses().map(([v,l])=>`<option value="${v}" ${v===filter?'selected':''}>${countedLabel(l,statusCounts.get(v))}</option>`).join('')}</select></div>${visibilityControls()}
 <p class="help" id="material-count" role="status" aria-live="polite">${t(`当前显示 ${materials.length} 条`,`Showing ${materials.length} items`)}</p>
 ${materials.length?`<div class="materials">${materials.map(m=>materialCard(m)).join('')}</div>`:isReview?`<div class="empty"><h3>${!user?t('登录后查看复习安排','Sign in to see your review'):reviewAll?t('还没有可复习的内容','No accessible learned items yet'):t('当前没有到期内容','Nothing due right now')}</h3><p>${t('可以主动复习、自由学习，或试试场景陪练。无需等待，也无需打卡。','Review early, explore lessons, or try a conversation. No waiting or check-ins required.')}</p><button data-page="words">${t('自由学习','Explore lessons')}</button></div>`:catalog.counts.length===0?empty():`<div class="empty"><h3>${t('没有符合条件的教材','No matching lessons')}</h3><p>${t('试试其他筛选条件。','Try another filter.')}</p></div>`}`;
}
function trainer(){
 const m=trainingItems[trainingIndex];if(!m)return `<h1>${t('这次练习结束了','You have finished this practice')}</h1><p>${t('可以再练一次，也可以到这里。学习数量由你决定。','Repeat, explore something else, or stop here. It is always your choice.')}</p><button data-page="home">${t('返回首页','Back to overview')}</button><button data-page="scenes">${t('试试场景交流','Try a conversation')}</button>`;
 return `<div class="sectionhead"><div><span class="eyebrow">${trainingReview?'REVIEW':'LISTEN & SPEAK'}</span><h1>${trainingReview?t('听说复习','Speaking review'):t('听一听，自己说一遍','Listen, then say it aloud')}</h1></div><button data-page="home">${t('随时结束','Finish anytime')}</button></div><p class="muted">${t('① 听发音　② 跟着读　③ 试着不看文字说出来','① Listen　② Repeat aloud　③ Try without the text')}</p>${visibilityControls()}${materialCard(m,true)}<div class="trainer-nav"><button id="previous-material" ${trainingIndex===0?'disabled':''}>← ${t('上一条','Previous')}</button><span>${trainingIndex+1} / ${trainingItems.length}</span><button class="primary" id="next-material">${t('下一条','Next')} →</button></div><p class="help">${user?t('位置和掌握状态保存到云端；跟读不录音、不评分，自己感受进步。','Position and learning states sync to the cloud. Speak aloud without recording or scoring.'):t('当前为自由体验。登录后可保存学习位置、掌握状态和复习时间。','Explore freely. Sign in to save your place, learning states, and review schedule.')}</p>`;
}
function practice(){
 const d=activeDialogue;if(!d)return dialogueList();const turn=d.turns[practiceTurn],roleName=r=>lang==='zh'?d.roles[r].zh:d.roles[r].en;
 return `<span class="eyebrow">SIMPLE CONVERSATION</span><div class="sectionhead"><h1>${esc(lang==='zh'?d.title_zh:d.title_en)}</h1><button data-page="scenes">${t('结束陪练','Leave practice')}</button></div><p class="help">${t('预设角色对话。对方说完后，你自己开口，再点“我说完了”。不录音，不做语音评分。','A preset role-play. Listen to the partner, speak your line aloud, then tap “I have said it”. No recording or speech scoring.')}</p><div class="practice-options"><span>${t('我扮演：','My role: ')}</span>${['a','b'].map(r=>`<button data-role="${r}" class="${practiceRole===r?'primary':''}" aria-pressed="${practiceRole===r}">${esc(roleName(r))}</button>`).join('')}</div>${visibilityControls()}
 ${turn?`<article class="material trainer-card dialogue-turn"><span class="badge">${turn.role===practiceRole?t('轮到你开口','Your turn to speak'):t('听听对方怎么说','Listen to your partner')} · ${esc(roleName(turn.role))}</span>${hideEnglish?`<p class="hidden-copy">${t('英文已隐藏，可以先听再说','English hidden. Listen, then speak.')}</p>`:`<h3 lang="en">${esc(turn.english)}</h3>`}${hideChinese?`<p class="hidden-copy">${t('中文已隐藏','Chinese hidden')}</p>`:`<p lang="zh-CN">${esc(turn.chinese)}</p>`}${audioControls('__dialogue')}<div class="trainer-nav"><span>${practiceTurn+1} / ${d.turns.length}</span><button class="primary" id="advance-dialogue">${turn.role===practiceRole?t('我说完了，下一句','I have said it · Next'):t('听懂了，下一句','I understand · Next')} →</button></div></article>`:`<div class="empty"><h2>${t('你完成了一次简单交流。','You completed a short conversation.')}</h2><p>${t('想换个角色再说一遍，或到这里结束，都可以。','Try the other role, repeat, or stop here. It is your choice.')}</p><button class="primary" id="restart-dialogue">${t('再练一次','Practise again')}</button><button data-page="scenes">${t('换个场景','Choose a scene')}</button></div>`}<p class="help">${user?t('陪练角色、当前句子和完成次数会同步到云端。','Your role, current turn, and completion count sync to the cloud.'):t('当前为访客体验。登录后可跨设备继续陪练。','Guest practice. Sign in to continue on another device.')}</p>`;
}
function paymentInstructions(o){if(!catalog.features?.manualPayment||o.status!=='pending'||!['wechat','alipay'].includes(o.payment_method))return '';const wechat=o.payment_method==='wechat';return `<div class="payment-instructions"><p>${t('请扫码支付人民币99元，核对收款人：','Scan to pay CNY 99. Check the recipient: ')}<strong>${esc(wechat?'杨超(*超)':'蜻蜓用车Dragonfly(*超)')}</strong></p><img src="/payments/${wechat?'wechat':'alipay'}.jpg" alt="${wechat?t('微信收款码','WeChat receiving QR'):t('支付宝收款码','Alipay receiving QR')}" width="${wechat?939:853}" height="1280"><p>${t('请核对金额为99元，在转账备注填写完整订单号：','Check the amount is CNY 99 and include this full order ID in the transfer note: ')}<code>${esc(o.id)}</code></p><p>${t('付款后提交审核。管理员核实真实到账后开通终身会员，截图或点击“我已付款”不会自动开通。','Submit after transferring. An administrator must verify actual settlement before activating lifetime membership. A screenshot or payment claim does not activate membership.')}</p></div>`;}
function membership(){return `<span class="eyebrow">INVEST IN YOURSELF</span><h1>${t('一次选择，长久学习。','A lifetime of learning.')}</h1><p class="muted">${t('选择适合自己的方式，让英语陪你走得更远。','Choose the way you learn best.')}</p><div class="plans"><article class="plan"><h3>${t('免费用户','Free')}</h3><div class="price">¥0</div><ul><li>${t('学习开放的免费教材','Access free lessons')}</li><li>${t('正常与慢速发音','Normal and slow audio')}</li><li>${t('云端保存学习记录','Cloud progress sync')}</li></ul><button class="outline" data-auth="register">${t('免费开始','Get started')}</button></article><article class="plan"><h3>${t('试用会员','Trial')}</h3><div class="price">1–90<small>${t('天','days')}</small></div><ul><li>${t('试用期内完整访问','Full access during your trial')}</li><li>${t('管理员开通与延期','Created and extended by an admin')}</li><li>${t('到期后保留学习记录','Progress retained after expiry')}</li></ul><span class="badge">${t('请联系网站管理员开通','Ask your site administrator')}</span></article><article class="plan featured"><span class="badge">${t('一次开通 · 永久有效','One time · Yours forever')}</span><h3>${t('永久会员','Lifetime')}</h3><div class="price">¥99<small>CNY</small></div><ul><li>${t('完整教材永久访问','Lifetime access to all lessons')}</li><li>${t('所有生活与商务场景','All life and business scenes')}</li><li>${t('不限次数学习与复习','Unlimited learning and review')}</li></ul>${mockEnabled()?`<button class="primary" id="create-order">${t('创建模拟订单','Create mock order')}</button>`:`<p class="help">${catalog.features?.manualPayment?t('请在下方创建99元订单并扫码付款。','Create a CNY 99 order below and scan to pay.'):t('当前暂不开放在线购买，请联系管理员申请试用。','Online purchases are unavailable. Contact the administrator for a trial.')}</p>`}</article></div><div class="banner"><div><strong>${mockEnabled()?t('当前为模拟订单，不会收取真实费用','Mock checkout · No real money charged'):catalog.features?.manualPayment?t('人工扫码收款 · 99元终身会员','Manual transfer · CNY 99 lifetime membership'):t('测试期间不收取费用','No payments during public testing')}</strong><p>${mockEnabled()?t('会员可访问完整教材。当前仅为模拟订单，真实支付尚未接入。','Members can access the full curriculum. Checkout is simulated; real payments are not connected.'):catalog.features?.manualPayment?t('付款申报不等于到账。管理员核实真实到账后开通终身会员。','A payment claim is not settlement. An administrator verifies actual receipt before activating lifetime membership.'):t('可由管理员开通试用或会员权限，不会自动扣费。','An administrator can grant trial or membership access. You will not be charged.')}</p></div></div><div class="panel"><h3>${t('人工付款申请','Manual payment request')}</h3><p class="help">${catalog.features?.manualPayment?t('创建订单后按所选方式扫码付款，请核对收款人、99元金额和完整订单编号。','Create an order, then scan its QR. Check the recipient, CNY 99 amount and full order ID.'):t('人工收款暂未开放，请勿付款。','Manual payments are unavailable. Please do not transfer funds.')}</p>${!catalog.features?.manualPayment||user?.membership==='lifetime'||user?.role==='admin'?'':`<form id="manual-order-form"><label>${t('付款方式','Payment method')}<select name="method"><option value="wechat">${t('微信','WeChat')}</option><option value="alipay">${t('支付宝','Alipay')}</option></select></label><button class="primary">${t('创建99元待付款订单','Create CNY 99 pending order')}</button></form>`}</div><div class="sectionhead"><h2>${t('我的订单','My orders')}</h2><button id="load-orders">${t('刷新订单','Refresh orders')}</button></div><div class="panel">${orders.length?orders.map(o=>`<div class="order"><code>${esc(o.id)}</code><strong>¥99 CNY</strong><span>${o.status==='paid'?t('已核实到账 · 终身会员','Verified · Lifetime'):o.status==='payment_claimed'?t('已申报付款 · 等待管理员核实','Claim submitted · Awaiting review'):o.status==='rejected'?t('审核未通过','Review rejected'):o.status==='mock_paid'?t('模拟已完成','Mock paid'):o.payment_method?t('待付款','Awaiting payment'):t('待模拟确认','Pending mock confirmation')}</span>${paymentInstructions(o)}${catalog.features?.manualPayment&&o.status==='pending'&&o.payment_method?`<button class="primary" data-claim="${esc(o.id)}">${t('我已付款，提交审核','I have paid · Submit for review')}</button>`:''}${o.status==='pending'&&!o.payment_method&&mockEnabled()?`<button class="primary" data-confirm="${esc(o.id)}">${t('模拟支付并开通','Simulate payment & activate')}</button>`:''}</div>`).join(''):`<p class="muted">${t('暂无订单。','No orders yet.')}</p>`}</div>`;}
function account(){if(!user)return `<h1>${t('我的账户','My account')}</h1><button class="primary" data-auth="login">${t('登录','Sign in')}</button>`;return `<h1>${t('我的账户','My account')}</h1><div class="panel"><h3>${esc(user.email)}</h3><p>${labelMembership(user)} ${user.trial_until?'· '+t('试用截止：','Trial until: ')+esc(new Date(user.trial_until).toLocaleString(lang==='zh'?'zh-CN':'en')):''}</p>${user.must_change_password?`<p class="error">${t('请先更改临时密码，之后即可学习。','Change your temporary password before continuing.')}</p>`:''}<h3>${t('修改密码','Change password')}</h3><form id="change-password"><label>${t('当前密码','Current password')}<input name="current" type="password" required autocomplete="current-password"></label><label>${t('新密码（12–128 位）','New password (12–128 characters)')}<input name="password" type="password" minlength="12" maxlength="128" required autocomplete="new-password"></label><button class="primary">${t('保存并重新登录','Save and sign in again')}</button></form></div><button id="logout">${t('退出登录','Sign out')}</button>`;}
function gmailPanel(){if(user?.email!=='sdqtyc@gmail.com')return '';return `<div class="panel"><h2>${t('Gmail 官方授权发信','Gmail authorized sending')}</h2><p>${gmailStatus.connected?t('已连接：','Connected: ')+esc(gmailStatus.sender):t('尚未完成 Google 授权。','Google authorization is incomplete.')}</p>${gmailStatus.configured?`<button id="gmail-connect">${t('通过 Google 授权发信','Authorize with Google')}</button>${gmailStatus.connected?`<button id="gmail-test">${t('发送 Gmail 验收邮件','Send Gmail acceptance email')}</button><button id="gmail-disconnect">${t('撤销发件授权','Revoke sending authorization')}</button>`:''}`:`<p>${t('请先按部署文档在 Render 安全配置 Google OAuth 客户端。','Configure the Google OAuth client in Render using the deployment instructions.')}</p><p>${t('授权回调地址：','Authorized redirect URI: ')}<code>${esc(gmailStatus.redirectUri||'')}</code></p>`}<p class="help">${t('只申请发信与核对账号身份的权限，不读取收件箱。连接和测试成功后仍需核对实际收件；不会自动开启支付。','Requests send and account identity permissions, without inbox access. Verify actual receipt after testing. Connecting does not enable payments.')}</p><div id="gmail-result" role="status"></div></div>`;}
function admin(){return `<span class="eyebrow">ADMINISTRATION</span><h1>${t('账号管理','Account management')}</h1>${gmailPanel()}<div class="sectionhead"><h2>${t('人工付款审核','Manual payment review')}</h2><button id="load-admin-orders">${t('刷新订单','Refresh orders')}</button></div><div class="panel">${adminOrders.length?adminOrders.map(o=>`<div class="order"><code>${esc(o.id)}</code><span>${esc(o.email)}</span><strong>¥99 CNY</strong><span>${esc(o.payment_method||'')}</span><span>${esc(o.status)}</span><span>${esc(o.notification_status||'pending')}</span>${o.notification_status&&o.notification_status!=='sent'?`<button data-notify="${esc(o.id)}">${t('重试邮件提醒','Retry notification')}</button>`:''}${o.status==='payment_claimed'?`<button data-review="approve" data-order="${esc(o.id)}">${t('核实到账并开通','Verify & activate')}</button><button data-review="reject" data-order="${esc(o.id)}">${t('拒绝','Reject')}</button>`:''}</div>`).join(''):`<p class="muted">${t('暂无人工付款订单','No manual orders')}</p>`}</div><div class="adminform"><h3>${t('创建试用账号','Create trial account')}</h3><form id="trial-form"><input name="email" type="email" placeholder="Email" aria-label="Email" required><input name="days" type="number" min="1" max="90" value="7" aria-label="${t('试用天数','Trial days')}" required><button class="primary">${t('创建并生成临时密码','Create & generate password')}</button></form><p class="help">${t('试用期 1–90 天。临时密码只显示一次，请安全交付；首次登录须更改。','Trial period: 1–90 days. Temporary passwords are shown once. A password change is required at first login.')}</p><div id="trial-result"></div></div><div class="sectionhead"><h2>${t('用户列表（最近 500 条）','Users (latest 500)')}</h2><button id="load-users">${t('刷新','Refresh')}</button></div><div class="tablewrap"><table><thead><tr><th>Email</th><th>${t('身份','Plan')}</th><th>${t('试用截止','Trial expiry')}</th><th>${t('状态','Status')}</th><th>${t('操作','Actions')}</th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.email)}</td><td>${esc(u.membership)}</td><td>${u.trial_until?esc(new Date(u.trial_until).toLocaleDateString()):'—'}</td><td>${u.disabled?t('已禁用','Disabled'):t('正常','Active')}</td><td>${u.role==='admin'?'Admin':`<button data-user="${esc(u.id)}" data-admin="extend">${t('延长试用','Extend trial')}</button><button data-user="${esc(u.id)}" data-admin="${u.disabled?'enable':'disable'}">${u.disabled?t('启用','Enable'):t('禁用','Disable')}</button><button data-user="${esc(u.id)}" data-admin="lifetime">${t('永久会员','Lifetime')}</button>`}</td></tr>`).join('')}</tbody></table></div>`;}
function render(){playback.stop();if(page!=='v2')learningV2.leave();document.documentElement.lang=lang==='zh'?'zh-CN':'en';const nav=[['classic','1.0',t('经典版学习首页','Classic overview')],['words','Aa',t('基础单词','Words')],['phrases','☷',t('实用短句','Phrases')],['scenes','▦',t('场景英语','Scenes')],['review','↻',t('我的复习','Review')],['v2','↔',t('听说联想','Listen & connect')],['membership','♧',t('会员中心','Membership')]];if(user?.role==='admin')nav.push(['admin','⚙',t('管理后台','Admin')]);$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="brandmark">Ee</div><div><strong>简单英语</strong><small>EASY ENGLISH</small></div></div><nav class="nav" aria-label="${t('主导航','Main navigation')}"><a class="version-nav-link" href="/" data-page="home" ${page==='home'?'aria-current="page"':''}>⌂ ${t('版本选择首页','Choose version')}</a><a class="version-nav-link" href="/ogden">2.0 ${t('现代基础英语','Modern Basic English')}</a>${nav.map(([p,i,l])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}><span aria-hidden="true">${i}</span>${l}</button>`).join('')}</nav><div class="sidebottom"><strong>${t('小小进步，大大不同。','Small steps, big possibilities.')}</strong><small>${t('你的英语之旅，从这里开始。','Your English journey begins here.')}</small></div></aside><main class="main"><header class="topbar"><span>${t('简单英语 · 全球学习空间','Easy English · Learning space')}<small> &nbsp; / &nbsp; ${t('欢迎回来','Welcome back')}</small></span><div class="topactions"><a class="version-switch" href="/" data-page="home">${t('切换版本','Switch version')}</a><button id="language" class="outline">${lang==='zh'?'EN / 中文':'中文 / EN'}</button>${user?`<button data-page="account" class="accountemail">${esc(labelMembership(user))}</button><button class="avatar" data-page="account" aria-label="${t('我的账户','My account')}">${esc(user.email[0].toUpperCase())}</button>`:`<button class="primary" data-auth="login">${t('登录 / 注册','Sign in')}</button>`}</div></header><div class="content">${page==='home'?versionHome():page==='classic'?home():page==='train'?trainer():page==='practice'?practice():['words','phrases','scenes','review'].includes(page)?learning():page==='v2'?'<div id="learning-v2-root"></div>':page==='membership'?membership():page==='admin'&&user?.role==='admin'?admin():account()}<footer class="sitefooter"><span>© ${new Date().getFullYear()} 简单英语 Easy English</span><span>${t('从零开始，与世界对话。','Start small. Connect with the world.')}</span><nav aria-label="${t('网站信息','Site information')}"><a href="/about">${t('应用说明','About')}</a> · <a href="/privacy">${t('隐私政策','Privacy')}</a> · <a href="/terms">${t('服务条款','Terms')}</a> · <a href="mailto:sdqtyc@gmail.com">${t('联系支持','Contact')}</a></nav></footer></div></main></div>`;bind();if(page==='v2')void learningV2.mount();}
function modal(content){playback.stop();$('#modal').innerHTML=`<div class="dialogtop"><strong>Easy English</strong><button id="close-modal" aria-label="Close">×</button></div>${content}`;$('#close-modal').onclick=()=>$('#modal').close();if(!$('#modal').open)$('#modal').showModal();}
function auth(mode='login',resetToken){const reset=mode==='reset',forgot=mode==='forgot',register=mode==='register';modal(`<h2>${reset?t('设置新密码','Set a new password'):forgot?t('找回密码','Reset your password'):register?t('开始你的英语之旅','Begin your journey'):t('欢迎回来','Welcome back')}</h2><form id="auth-form">${!reset?`<label>${t('邮箱','Email')}<input name="email" type="email" required autocomplete="email"></label>`:''}${!forgot?`<label>${t('密码','Password')}<input name="password" type="password" required minlength="${register||reset?12:1}" maxlength="128" autocomplete="${register||reset?'new-password':'current-password'}"></label>${register||reset?`<div class="help">${t('使用 12–128 位密码。','Use a password with 12–128 characters.')}</div>`:''}`:''}<div class="error" id="auth-error" role="alert"></div><button class="primary">${reset?t('重置密码','Reset password'):forgot?t('发送重置链接','Send reset link'):register?t('注册','Create account'):t('登录','Sign in')}</button></form>${!reset?`<div class="formlinks"><button data-auth="${register?'login':'register'}">${register?t('已有账号，登录','Already registered? Sign in'):t('没有账号？免费注册','New here? Create account')}</button>${catalog.features?.passwordReset!==false?`<button data-auth="forgot">${t('忘记密码','Forgot password?')}</button>`:''}</div>`:''}`);
 $('#modal').querySelectorAll('[data-auth]').forEach(el=>el.onclick=()=>auth(el.dataset.auth));$('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;const values=Object.fromEntries(new FormData(e.target));try{await request('/auth/'+mode,'POST',{...values,...reset?{token:resetToken}:{}});if(forgot){modal(`<h2>${t('请查看邮箱','Check your inbox')}</h2><p>${t('如果账号存在，将发送重置链接。链接有效期为 30 分钟。','If your account exists, a reset link will be sent. It expires in 30 minutes.')}</p>`);return;}$('#modal').close();if(reset){history.replaceState(null,'','/');toast(t('密码已重置，请登录','Password reset. Please sign in.'));auth('login');}await refresh();if(!user?.must_change_password){page='home';history.replaceState(null,'','/');}render();}catch(err){$('#auth-error').textContent=err.message;}finally{button.disabled=false;}};
}
async function navigate(p,writeHistory=true){
 if(p!=='home'&&!classicPages.has(p))p='home';
 playback.stop();search='';filter='all';scene='all';difficulty='all';category='all';
 try{if(user&&!user.must_change_password&&['home','classic','words','phrases','scenes','review'].includes(p))await refresh();
 if(user?.must_change_password)p='account';
 if(p==='admin'&&user?.role!=='admin')p='account';
 if(p==='admin'&&user?.role==='admin'){const [a,o,g]=await Promise.all([request('/admin/users'),request('/admin/orders'),user.email==='sdqtyc@gmail.com'?request('/admin/mail/gmail/status'):Promise.resolve({})]);users=a.users;adminOrders=o.orders;gmailStatus=g;}
 if(p==='membership'&&user)orders=(await request('/orders')).orders;
 page=p;if(writeHistory)history.pushState?.({page:p},'',pageUrl(p));render();window.scrollTo(0,0);}catch(e){toast(e.message);}
}

function bind(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=e=>{e?.preventDefault?.();return navigate(el.dataset.page);});document.querySelectorAll('[data-auth]').forEach(el=>el.onclick=()=>auth(el.dataset.auth));$('#language').onclick=()=>{lang=lang==='zh'?'en':'zh';localStorage.setItem('ee_lang',lang);render();};
 if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;render();};if($('#scene'))$('#scene').onchange=e=>{scene=e.target.value;render();};
 bindLearning();
 if($('#logout'))$('#logout').onclick=async()=>{try{await request('/auth/logout','POST',{});user=null;orders=[];page='home';history.replaceState(null,'','/');await refresh();render();}catch(e){toast(e.message);}};
 if($('#change-password'))$('#change-password').onsubmit=async e=>{e.preventDefault();try{await request('/auth/password','POST',Object.fromEntries(new FormData(e.target)));await refresh();render();auth('login');}catch(e){toast(e.message);}};
 document.querySelectorAll('[data-notify]').forEach(el=>el.onclick=async()=>{try{const r=await request('/admin/orders/notify','POST',{id:el.dataset.notify});await navigate('admin');toast(r.notification);}catch(e){toast(e.message);}});
 if($('#manual-order-form'))$('#manual-order-form').onsubmit=async e=>{e.preventDefault();if(!user)return auth('login');try{const method=new FormData(e.target).get('method');await request('/orders/manual','POST',{method});orders=(await request('/orders')).orders;render();toast(t('订单已创建。请核对下方收款人和订单号，实际付款后再申报。','Order created. Check the recipient and order ID below. Submit a claim only after transferring funds.'));}catch(error){toast(error.message);}};
 document.querySelectorAll('[data-claim]').forEach(el=>el.onclick=()=>{modal(`<h2>${t('申报已付款','Claim payment')}</h2><p>${t('只有实际完成转账后才可提交。提交不会立即开通会员，管理员必须核对实际到账。','Submit only after a real transfer. Membership is activated only after administrator verification.')}</p><button class="primary" id="claim-confirm">${t('我已实际付款','I have paid')}</button>`);$('#claim-confirm').onclick=async()=>{try{await request('/orders/manual/claim','POST',{id:el.dataset.claim});$('#modal').close();orders=(await request('/orders')).orders;render();toast(t('已提交审核','Submitted for review'));}catch(error){toast(error.message);}};});
 if($('#create-order'))$('#create-order').onclick=async()=>{if(!user)return auth('login');try{await request('/orders','POST',{});orders=(await request('/orders')).orders;render();toast(t('模拟订单已创建，不收取真实费用','Mock order created. No real charge.'));}catch(e){toast(e.message);}};
 if($('#load-orders'))$('#load-orders').onclick=()=>navigate('membership');document.querySelectorAll('[data-confirm]').forEach(el=>el.onclick=()=>{modal(`<h2>${t('确认模拟开通','Confirm mock activation')}</h2><p>${t('此操作不扣款，将该账号升级为永久会员。订单金额为 99 元人民币。','No money will be charged. This mock CNY 99 order grants lifetime membership.')}</p><button class="primary" id="confirm-mock">${t('确认模拟支付','Confirm mock payment')}</button>`);$('#confirm-mock').onclick=async()=>{try{await request('/orders/confirm','POST',{id:el.dataset.confirm});$('#modal').close();await refresh();await navigate('membership');toast(t('永久会员已模拟开通','Lifetime membership activated via mock payment'));}catch(e){toast(e.message);}};});
 if($('#gmail-connect'))$('#gmail-connect').onclick=async()=>{try{const r=await request('/admin/mail/gmail/start','POST',{});window.location.assign(r.authorizationUrl);}catch(e){toast(e.message);}};
 if($('#gmail-test'))$('#gmail-test').onclick=async()=>{const button=$('#gmail-test');button.disabled=true;try{const r=await request('/admin/mail/gmail/test','POST',{});$('#gmail-result').textContent=t('Google 已接受，请在 Gmail 核对验收编号：','Google accepted. Check this ID in Gmail: ')+r.testId;}catch(e){toast(e.message);}finally{button.disabled=false;}};
 if($('#gmail-disconnect'))$('#gmail-disconnect').onclick=async()=>{if(!window.confirm(t('确认撤销网站的 Gmail 发件授权？','Revoke the website Gmail sending permission?')))return;try{await request('/admin/mail/gmail/disconnect','POST',{});await navigate('admin');}catch(e){toast(e.message);}};
 if($('#load-admin-orders'))$('#load-admin-orders').onclick=()=>navigate('admin');
 document.querySelectorAll('[data-review]').forEach(el=>el.onclick=()=>{const action=el.dataset.review;modal(`<h2>${t('人工核实付款','Verify manual payment')}</h2><p>${t('请先在真实收款账户中核对金额、时间与订单编号。客户申报或截图不是到账凭证。','Check actual funds in your payment account first. A claim or screenshot is not proof.')}</p><button class="primary" id="review-confirm">${action==='approve'?t('已核实到账，确认开通','Payment verified · Activate'):t('确认拒绝订单','Reject order')}</button>`);$('#review-confirm').onclick=async()=>{try{await request('/admin/orders/review','POST',{id:el.dataset.order,action,verified:action==='approve'});$('#modal').close();await navigate('admin');toast(t('订单已处理','Order reviewed'));}catch(e){toast(e.message);}};});
 if($('#load-users'))$('#load-users').onclick=()=>navigate('admin');if($('#trial-form'))$('#trial-form').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));try{const r=await request('/admin/trials','POST',{email:v.email,days:Number(v.days)});users=(await request('/admin/users')).users;render();$('#trial-result').innerHTML=`<p class="secret">${esc(r.user.email)}<br>${t('临时密码（仅显示一次）：','Temporary password (shown once): ')}<strong>${esc(r.temporaryPassword)}</strong></p>`;}catch(e){toast(e.message);}};
 document.querySelectorAll('[data-admin]').forEach(el=>el.onclick=()=>{const action=el.dataset.admin;modal(`<h2>${t('确认账号操作','Confirm account action')}</h2><p>${esc(users.find(u=>u.id===el.dataset.user)?.email)} · ${esc(action)}</p><form id="admin-action">${action==='extend'?`<label>${t('延长天数（1–90）','Extend by days (1–90)')}<input name="days" type="number" min="1" max="90" value="7" required></label>`:''}<button class="primary">${t('确认','Confirm')}</button><div id="admin-error" class="error" role="alert"></div></form>`);$('#admin-action').onsubmit=async e=>{e.preventDefault();try{await request('/admin/users','PATCH',{id:el.dataset.user,action,days:Number(new FormData(e.target).get('days'))});$('#modal').close();await navigate('admin');}catch(e){$('#admin-error').textContent=e.message;}};});
}
window.addEventListener('popstate',()=>{void navigate(routePage(location.search),false);});
(async()=>{try{await refresh();if(page==='admin'&&user?.role!=='admin')page='account';if(['admin','membership'].includes(page))await navigate(page,false);else render();const resetToken=new URLSearchParams(location.search).get('reset');if(resetToken){history.replaceState(null,'','/');auth('reset',resetToken);}else if(new URLSearchParams(location.search).get('login')==='1'&&!user)auth('login');}catch{document.querySelector('#app').innerHTML='<div class="empty"><h1>简单英语 Easy English</h1><p>服务暂不可用，请稍后刷新。<br>Service unavailable. Please refresh later.</p></div>';}})();

async function rememberMaterial(id){
 if(user){await request('/learning-state','PUT',{material_id:id});learningState={last_material_id:id};}
}
async function startTraining(items,index=0,isReview=false){
 if(!items[index]){toast(t('暂时没有可用教材，可以先试试场景陪练。','No lessons are available yet. Try a preset conversation.'));return navigate('scenes');}
 await rememberMaterial(items[index].id);trainingItems=items;trainingIndex=index;trainingReview=isReview;page='train';render();window.scrollTo(0,0);
}
async function saveDialogue(role,index){
 if(user)await request('/practice-progress','PUT',{dialogue_id:activeDialogue.id,role,turn_index:index});
 practiceRole=role;practiceTurn=index;
 if(user)practiceProgress=(await request('/practice-progress')).practice;
 render();
}
function bindLearning(){
 document.querySelectorAll('[data-v2-token]').forEach(el=>el.onclick=async()=>{if(!user)return auth('login');if(el.disabled)return;el.disabled=true;try{const data=await request('/learning-v2/links?material_id='+encodeURIComponent(el.dataset.v2Phrase));const token=el.dataset.v2Token.toLowerCase().replace(/[’‘]/g,"'");const word=findLinkedWord(data.materials,token);toast(word?word.english+' · '+word.chinese:t('现有基础词库暂无此词，请参考整句翻译。','This word is not in the basic dictionary yet. See the sentence translation.'));}catch(e){toast(e.message);}finally{el.disabled=false;}});

 for(const [attribute,mode] of [['data-v2-related','linked'],['data-v2-listen','listening'],['data-v2-expression','expression']])document.querySelectorAll('['+attribute+']').forEach(el=>el.onclick=()=>{if(!user)return auth('login');learningV2.open(mode,el.getAttribute(attribute));page='v2';render();});
 if($('#difficulty'))$('#difficulty').onchange=e=>{difficulty=e.target.value;render();};
 if($('#category'))$('#category').onchange=e=>{category=e.target.value;render();};
 if($('#practice-scene'))$('#practice-scene').onchange=e=>{practiceScene=e.target.value;render();};
 const safely=(el,fn)=>{el.onclick=async()=>{if(el.disabled)return;el.disabled=true;try{await fn();}catch(error){toast(error.message);}finally{el.disabled=false;}};};
 document.querySelectorAll('[data-continue]').forEach(el=>safely(el,async()=>{
  if(user?.must_change_password)return navigate('account');
  if(user)await refresh();
  let index=catalog.materials.findIndex(m=>m.id===learningState?.last_material_id);
  if(index<0)index=catalog.materials.findIndex(m=>!progress.some(p=>p.material_id===m.id));
  await startTraining(catalog.materials,Math.max(0,index));
 }));
 document.querySelectorAll('[data-train]').forEach(el=>safely(el,async()=>{
  const items=page==='review'?reviewItems:catalog.materials;
  await startTraining(items,items.findIndex(m=>m.id===el.dataset.train),page==='review');
 }));
 document.querySelectorAll('[data-hide]').forEach(el=>el.onclick=()=>{if(el.dataset.hide==='en')hideEnglish=!hideEnglish;else hideChinese=!hideChinese;render();});
 if($('#slow-audio'))$('#slow-audio').onclick=()=>{slowAudio=!slowAudio;render();};
 const playFrom=(el,repeat=false,shadow=false)=>{
  const id=el.dataset.speak||el.dataset.repeat||el.dataset.shadow;
  const item=id==='__dialogue'?activeDialogue?.turns[practiceTurn]:catalog.materials.find(m=>m.id===id);
  if(!item)return;
  if(el.dataset.speed){
   slowAudio=el.dataset.speed==='slow';
   document.querySelectorAll('[data-speed]').forEach(button=>button.setAttribute('aria-pressed',String((button.dataset.speed==='slow')===slowAudio)));
   const toggle=$('#slow-audio');if(toggle){toggle.setAttribute('aria-pressed',String(slowAudio));toggle.textContent=slowAudio?t('重复/陪练：慢速','Repeat/dialogue: slow'):t('重复/陪练：正常','Repeat/dialogue: normal');}
  }
  document.querySelectorAll('.playback-phase').forEach(node=>node.textContent='');
  const output=el.closest('.material')?.querySelector('.playback-phase');
  playback.play(item,{slow:slowAudio,repeat,shadow,
   onPhase:phase=>{if(output)output.textContent=phase==='listen'?t(slowAudio?'正在慢速播放，先听一听…':'正在正常播放，先听一听…',slowAudio?'Listening slowly…':'Listening normally…'):phase==='speak'?t('轮到你跟读，稍后自动重复。随时可以停止。','Your turn to speak. Audio repeats after a pause; stop anytime.'):phase==='pause'?t('稍停一下，马上重复…','A short pause before repeating…'):t('听完了，可以自己说一遍。','Now try saying it aloud.');},
   onError:()=>{if(output)output.textContent=t('播放不可用，请重试或更换浏览器。','Playback unavailable. Please retry or use another browser.');}
  });
 };
 document.querySelectorAll('[data-speak]').forEach(el=>el.onclick=()=>playFrom(el));
 document.querySelectorAll('[data-repeat]').forEach(el=>el.onclick=()=>playFrom(el,true));
 document.querySelectorAll('[data-shadow]').forEach(el=>el.onclick=()=>playFrom(el,true,true));
 document.querySelectorAll('[data-stop]').forEach(el=>el.onclick=()=>{playback.stop();document.querySelectorAll('.playback-phase').forEach(node=>node.textContent=t('已停止。随时可以继续。','Stopped. Continue whenever you like.'));});
 document.querySelectorAll('[data-status]').forEach(el=>safely(el,async()=>{
  if(!user)return auth('login');
  playback.stop();await request('/progress','PUT',{material_id:el.dataset.material,status:el.dataset.status});learningState={last_material_id:el.dataset.material};await syncLearning();render();
 }));
 document.querySelectorAll('[data-review-mode]').forEach(el=>safely(el,async()=>{
  const all=el.dataset.reviewMode==='all';const next=user?(await request(all?'/review/all':'/review')).items:[];
  reviewAll=all;reviewItems=next;render();
 }));
 if($('[data-start-review]'))safely($('[data-start-review]'),async()=>{
  const visible=[...document.querySelectorAll('[data-train]')].map(el=>reviewItems.find(m=>m.id===el.dataset.train)).filter(Boolean);await startTraining(visible,0,true);
 });
 if($('#previous-material'))safely($('#previous-material'),async()=>{const next=trainingIndex-1;if(next<0)return;await rememberMaterial(trainingItems[next].id);trainingIndex=next;render();});
 if($('#next-material'))safely($('#next-material'),async()=>{const next=trainingIndex+1;if(trainingItems[next])await rememberMaterial(trainingItems[next].id);trainingIndex=next;render();});
 if($('#practice-category'))$('#practice-category').onchange=e=>{practiceCategory=e.target.value;render();};
 document.querySelectorAll('[data-dialogue]').forEach(el=>safely(el,async()=>{
  if(user?.must_change_password)return navigate('account');
  const d=catalog.dialogues.find(d=>d.id===el.dataset.dialogue);if(!d)return;
  const saved=practiceProgress.find(p=>p.dialogue_id===d.id);
  const role=saved?.role||'a',index=saved&&saved.turn_index<d.turns.length?saved.turn_index:0;
  if(user)await request('/practice-progress','PUT',{dialogue_id:d.id,role,turn_index:index});
  activeDialogue=d;practiceRole=role;practiceTurn=index;page='practice';render();window.scrollTo(0,0);
 }));
 document.querySelectorAll('[data-role]').forEach(el=>safely(el,()=>saveDialogue(el.dataset.role,0)));
 if($('#advance-dialogue'))safely($('#advance-dialogue'),()=>saveDialogue(practiceRole,practiceTurn+1));
 if($('#restart-dialogue'))safely($('#restart-dialogue'),()=>saveDialogue(practiceRole,0));
}
